{
  "command": "for u in 'http://127.0.0.1:4173/' 'http://127.0.0.1:4173/resume.pdf' 'https://github.com/nickborrello' 'https://www.linkedin.com/in/nicholasborrello/' 'https://resumancer.dev' 'https://github.com/nickborrello/NEVI-Search-Tool'; do printf '%s -> ' \"$u\"; curl -L -sS -o /dev/null --max-time 20 -w '%{http_code} %{url_effective}\\n' \"$u\" || echo CURL_FAILED; done",
  "timeout": 150
}

{
  "command": "file public/resume.pdf public/og-card.png public/work/* && (command -v pdftotext >/dev/null && pdftotext public/resume.pdf - | sed -n '1,100p' || true) && stat -f '%Sm %N' -t '%Y-%m-%d %H:%M:%S' /tmp/qa/*.png data.ts public/resume.pdf",
  "timeout": 30
}

{
  "command": "if command -v tesseract >/dev/null; then for f in /tmp/qa/*.png; do echo ===$f===; tesseract \"$f\" stdout 2>/dev/null | sed -n '1,100p'; done; else echo 'tesseract not installed'; fi",
  "timeout": 120
}

{
  "command": "nl -ba App.tsx | sed -n '1,120p'; nl -ba data.ts | sed -n '1,380p'; nl -ba .impeccable/surfaces/index-html.md | sed -n '1,100p'; nl -ba DESIGN.md | sed -n '1,140p'",
  "timeout": 30
}

