  1	import React, { useEffect, useRef, useState } from 'react';
  2	
  3	interface SectionProps {
  4	  id: string;
  5	  index: string;
  6	  label: string;
  7	  heading: string;
  8	  intro?: string;
  9	  children: React.ReactNode;
 10	}
 11	
 12	export const Section: React.FC<SectionProps> = ({ id, index, label, heading, intro, children }) => {
 13	  const headRef = useRef<HTMLDivElement>(null);
 14	  const [revealed, setRevealed] = useState(false);
 15	
 16	  useEffect(() => {
 17	    const el = headRef.current;
 18	    if (!el) return;
 19	    const observer = new IntersectionObserver(
 20	      ([entry]) => {
 21	        if (entry.isIntersecting) {
 22	          setRevealed(true);
 23	          observer.disconnect();
 24	        }
 25	      },
 26	      { threshold: 0.2 }
 27	    );
 28	    observer.observe(el);
 29	    // Safety net: never leave the heading hidden
 30	    const fallback = window.setTimeout(() => setRevealed(true), 2000);
 31	    return () => {
 32	      observer.disconnect();
 33	      window.clearTimeout(fallback);
 34	    };
 35	  }, []);
 36	
 37	  return (
 38	    <section id={id} aria-labelledby={`${id}-heading`} className="scroll-mt-28">
 39	      {/* Divider strip — the world's frame device */}
 40	      <div aria-hidden="true" className="mesh-strong relative h-9 border-y border-nier-dark/15">
 41	        <span className="absolute left-0 top-0 h-2.5 w-2.5 border-l border-t border-nier-dark/50" />
 42	        <span className="absolute right-0 top-0 h-2.5 w-2.5 border-r border-t border-nier-dark/50" />
 43	        <span className="absolute bottom-0 left-0 h-2.5 w-2.5 border-l border-b border-nier-dark/50" />
 44	        <span className="absolute bottom-0 right-0 h-2.5 w-2.5 border-r border-b border-nier-dark/50" />
 45	      </div>
 46	
 47	      <div className="max-w-6xl mx-auto px-5 sm:px-8 py-16 sm:py-24">
 48	        <div ref={headRef} className={revealed ? 'rise-in' : 'opacity-0'}>
 49	          <div className="flex items-center gap-4">
 50	            <span className="font-tech font-semibold tracking-[0.22em] text-[11px] text-nier-dark uppercase whitespace-nowrap">
 51	              {index} / {label}
 52	            </span>
 53	            <span aria-hidden="true" className="h-px flex-1 bg-nier-dark/15" />
 54	          </div>
 55	
 56	          <h2
 57	            id={`${id}-heading`}
 58	            className="mt-5 font-tech font-bold text-4xl sm:text-5xl tracking-[0.01em] text-nier-darker"
 59	          >
 60	            {heading}
 61	          </h2>
 62	
 63	          {intro && (
 64	            <p className="mt-4 max-w-2xl text-[15px] leading-relaxed text-nier-dark/90">{intro}</p>
 65	          )}
 66	        </div>
 67	
 68	        <div className="mt-10 sm:mt-12">{children}</div>
 69	      </div>
 70	    </section>
 71	  );
 72	};
